package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

public class JsonWriter_value_TriageGen0Test {

    @Test
    public void testValue_withNonNullString() throws IOException {
        StringWriter sw = new StringWriter();
        JsonWriter writer = new JsonWriter(sw);

        // Preparation: start an object and a name to satisfy writeDeferredName() and beforeValue()
        writer.beginObject();
        writer.name("testKey");

        // Execution
        JsonWriter result = writer.value("hello");

        // Verification
        assertEquals(writer, result);
        assertEquals("{\"testKey\":\"hello\"", sw.toString());
    }






}

package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
