import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

public class JsonWriter_value_TriageGen0Test {







    @Test
    public void testValue_withSpecialCharacters() throws IOException {
        StringWriter sw = new StringWriter();
        JsonWriter writer = new JsonWriter(sw);

        writer.beginObject();
        writer.name("special");

        // Testing string escaping (handled by string(value) called inside value(String))
        writer.value("quote\" and backslash\\");

        assertEquals("{\"special\":\"quote\\\" and backslash\\\\\"}", sw.toString());
    }
}
